    "transcript": "男の人が、パソコン会社のサービスセンターに電話をしています。\nサービスセンターでは、このあと、どうすると言っていますか。\n女：はい、サクラ電子サービスセンター、ハードウエア係です。\n男：あの、パソコン、壊れてるんですが。\n女：はい。では、どのような状態かご説明いただけますか。\n男：ええ。DVDが見られないんですよ。\n女：DVDですね。\n男：ええ。DVDを入れて起動しようとすると、何回やっても強制終了になっちゃうんですよ。\n女：そうですか。そうしますと、ソフトに問題があると考えられますので、ソフト部門の者にお回しします。少々お待ちください。\n……\n申し訳ございません。ただいま、ふさがっているようですので、折り返しご連絡させるようにいたしますが。\n男：いつ頃になりますか。\n女：このあとすぐに、お電話、差し上げられると思います。\n男：そうですか。お願いします。\n女：はい、かしこまりました。\nサービスセンターでは、このあと、どうすると言っていますか。\n① ハードの担当者が電話をする。\n② ソフトの担当者が電話をする。\n③ ハードを点検する。\n④ ソフトを点検する。",
    "transcriptWithFurigana": "男(おとこ)の人(ひと)が、パソコン会社(かいしゃ)のサービスセンターに電話(でんわ)をしています。\nサービスセンターでは、このあと、どうすると言(い)っていますか。\n女(おんな)：はい、サクラ電(でん)子(こ)サービスセンター、ハードウエア係(かかり)です。\n男(おとこ)：あの、パソコン、壊(こわ)れてるんですが。\n女(おんな)：はい。では、どのような状態(じょうたい)かご説明(せつめい)いただけますか。\n男(おとこ)：ええ。DVDが見(み)られないんですよ。\n女(おんな)：DVDですね。\n男(おとこ)：ええ。DVDを入(い)れて起動(きどう)しようとすると、何回(なんかい)やっても強制終了(きょうせいしゅうりょう)になっちゃうんですよ。\n女(おんな)：そうですか。そうしますと、ソフトに問題(もんだい)があると考(かんが)えられますので、ソフト部門(ぶもん)の者(もの)にお回(かい)しします。少々(しょうしょう)お待(ま)ちください。\n……\n申(もう)し訳(わけ)ございません。ただいま、ふさがっているようですので、折(お)り返(かえ)しご連絡(れんらく)させるようにいたしますが。\n男(おとこ)：いつ頃(ころ)になりますか。\n女(おんな)：このあとすぐに、お電話(でんわ)、差(さ)し上(あ)げられると思(おも)います。\n男(おとこ)：そうですか。お願(ねが)いします。\n女(おんな)：はい、かしこまりました。\nサービスセンターでは、このあと、どうすると言(い)っていますか。\n① ハードの担当者(たんとうしゃ)が電話(でんわ)をする。\n② ソフトの担当者(たんとうしゃ)が電話(でんわ)をする。\n③ ハードを点検(てんけん)する。\n④ ソフトを点検(てんけん)する。",
    "translationZhTW": "一名男子打電話到電腦公司的服務中心。\n服務中心說接下來會怎麼處理？\n女：您好，這裡是櫻花電子服務中心硬體部門。\n男：那個，我的電腦壞了。\n女：好的。可以請您說明一下目前是什麼狀況嗎？\n男：嗯，DVD看不了。\n女：DVD是嗎？\n男：對。放入DVD想啟動時，不管試幾次都會被強制關閉。\n女：這樣啊。這樣看來應該是軟體方面有問題，我幫您轉到軟體部門。請稍等。\n……\n非常抱歉，現在好像電話都佔線，我請他們稍後回電給您，可以嗎？\n男：大概什麼時候？\n女：我想等一下馬上就能打給您。\n男：這樣啊，那麻煩了。\n女：好的，明白了。\n服務中心說接下來會怎麼處理？\n① 硬體負責人會打電話。\n② 軟體負責人會打電話。\n③ 檢查硬體。\n④ 檢查軟體。",
