    "transcript": "男の人と女の人が、取引先の入金の状況について話しています。\n女の人は、このあと、何をしますか。\n男：うわー、まいったなあ。\n女：どうしたんですか？\n男：ヤマシタ物産からの入金なんだけど、今日も入ってないんだよ。\n女：えー、まだなの？\n男：うん、メールでプッシュするのも、もう、何回目だろ。\n女：金利が、ばかにならないもんね。\n男：うん。週明けには入ってるって、返事だったのに……。電話するしかないか。あ、でも、今日、これからずっと外回りだ。\n女：わたし、代わりにやっとこうか？\n男：お願いできるかなあ。\n女：ええ、担当者と何度か話したことあるから。まかせといて。\n男：助かるよ。\n女の人は、このあと、何をしますか。\n① 入金の確認をする。\n② メールを出す。\n③ 電話をする。\n④ 外出する。",
