    "translationZhTW": "一名男子和一名女子正在談客戶付款的狀況。\n女子接下來會做什麼？\n男：唉，真傷腦筋。\n女：怎麼了？\n男：山下物產的款項，今天還是沒入帳。\n女：欸？還沒嗎？\n男：嗯，我用Email催款都不知道第幾次了。\n女：利息成本也不能小看啊。\n男：對啊。明明回覆說週初就會匯進來……。看來只能打電話了。啊，不過我今天接下來一整天都要跑外勤。\n女：要不要我替你打？\n男：可以麻煩你嗎？\n女：可以啊，我跟負責人也談過幾次。交給我吧。\n男：幫大忙了。\n女子接下來會做什麼？\n① 確認款項是否入帳。\n② 寄Email。\n③ 打電話。\n④ 外出。",
