    "id": "BJT_JP02_P1_S3_Q07",
    "transcript": "男の人と女の人が、社内の新人研修について話しています。\n女の人は、研修で、どんなことを教えたらいいと言っていますか。\n男：ちょっと、これ、新人研修のプログラム、見た？\n女：ええ。\n男：今年は、いろいろ新しいのが増えたよね。パソコン入門とか。\n女：そう？いまどき、別に新しいとは思わないけどな。それに、なんだか座学が多くて、ちょっとね。\n男：たとえば？\n女：うーん。まず、いまどき「パソコン入門」なんて無用だと思うし、総務部の「企業倫理」もねえ。\n男：なんで？\n女：だって、そんなこと、わざわざ教えなければ通用しないような人は、もともと面接で落とされてるわけでしょ。\n男：なるほどね。\n女：それに他の部も。なんか「入門」とか「事業説明」っていうことばが多いと思わない？\n男：え？\n女：まあ、そういう時間も導入として必要かもしれないけどね。もっとこう、現場のことを教えたほうが、新人には、役に立つと思うんだけどな。\n男：そういえば、確かに、ぼくも眠くなった覚えがあるよ。\n女の人は、研修で、どんなことを教えたらいいと言っていますか。\n① コンピュータの使い方\n② 会社員の心がまえ\n③ 会社の事業内容\n④ 会社での実務",
    "transcriptWithFurigana": "男(おとこ)の人(ひと)と女(おんな)の人(ひと)が、社内(しゃない)の新人研修(しんじんけんしゅう)について話(はな)しています。\n女(おんな)の人(ひと)は、研修(けんしゅう)で、どんなことを教(おし)えたらいいと言(い)っていますか。\n男(おとこ)：ちょっと、これ、新人研修(しんじんけんしゅう)のプログラム、見(み)た？\n女(おんな)：ええ。\n男(おとこ)：今年(ことし)は、いろいろ新(しん)しいのが増(ふ)えたよね。パソコン入門(にゅうもん)とか。\n女(おんな)：そう？いまどき、別(べつ)に新(しん)しいとは思(おも)わないけどな。それに、なんだか座学(ざがく)が多(おお)くて、ちょっとね。\n男(おとこ)：たとえば？\n女(おんな)：うーん。まず、いまどき「パソコン入門(にゅうもん)」なんて無用(むよう)だと思(おも)うし、総務部(そうむぶ)の「企業倫理(きぎょうりんり)」もねえ。\n男(おとこ)：なんで？\n女(おんな)：だって、そんなこと、わざわざ教(おし)えなければ通用(つうよう)しないような人(ひと)は、もともと面接(めんせつ)で落(お)とされてるわけでしょ。\n男(おとこ)：なるほどね。\n女(おんな)：それに他(ほか)の部(ぶ)も。なんか「入門(にゅうもん)」とか「事業説明(じぎょうせつめい)」っていうことばが多(おお)いと思(おも)わない？\n男(おとこ)：え？\n女(おんな)：まあ、そういう時間(じかん)も導入(どうにゅう)として必要(ひつよう)かもしれないけどね。もっとこう、現場(げんば)のことを教(おし)えたほうが、新人(しんじん)には、役(やく)に立(た)つと思(おも)うんだけどな。\n男(おとこ)：そういえば、確(かく)かに、ぼくも眠(ねむ)くなった覚(おぼ)えがあるよ。\n女(おんな)の人(ひと)は、研修(けんしゅう)で、どんなことを教(おし)えたらいいと言(い)っていますか。\n① コンピュータの使(つか)い方(かた)\n② 会社員(かいしゃいん)の心(こころ)がまえ\n③ 会社(かいしゃ)の事(じ)業(ぎょう)内容(ないよう)\n④ 会社(かいしゃ)での実務(じつむ)",
    "translationZhTW": "一名男子和一名女子正在談公司內部的新進員工研修。\n女子認為研修應該教什麼？\n男：你看過這個新人研修課程了嗎？\n女：看過。\n男：今年增加了不少新東西吧，比如電腦入門。\n女：是嗎？現在這年代，我倒不覺得那有多新。而且總覺得課堂講授太多了，有點……。\n男：比如說？\n女：嗯，首先現在還教「電腦入門」我覺得沒必要，總務部的「企業倫理」也是。\n男：為什麼？\n女：因為如果連這種事都要特地教才懂的人，本來面試時就應該被刷掉了吧。\n男：有道理。\n女：而且其他部門也是。你不覺得「入門」、「事業說明」這種詞很多嗎？\n男：欸？\n女：當然這種時間作為導入也許有必要，但我覺得多教一些實際現場的事情，對新人會更有幫助。\n男：這麼說來，我確實也記得自己以前聽到想睡覺。\n女子認為研修應該教什麼？\n① 電腦的使用方法\n② 公司職員應有的心態\n③ 公司的事業內容\n④ 公司實際工作的內容",
