    "transcript": "男の人と女の人が話しています。\n男の人は、このあと、取引先にどのような内容のメールを書きますか。\n男：課長、ただいま帰りました。\n女：ご苦労さん。どうだった？\n男：うまくいきましたよ。決まりです。\n女：そう。アサヒ製作所さん、見積もりの条件、のんでくれた？\n男：いえ、けっこう粘られました。\n女：そうだろうね。\n男：ええ。でも、他社の条件、引合いに出したら、しぶしぶでしたけど、首をタテに振ってくれました。\n女：そう！\n男：早速、契約書、整えます。\n女：うん。あ、契約書できたら、事前に、案を先方にメールしといてね。\n男：はい。\n女：それと、旅費の精算書も早くね。\n男の人は、このあと、取引先にどのような内容のメールを書きますか。\n① 見積書\n② 契約書\n③ 契約書の案\n④ 旅費の精算書",
    "transcriptWithFurigana": "男(おとこ)の人(ひと)と女(おんな)の人(ひと)が話(はな)しています。\n男(おとこ)の人(ひと)は、このあと、取引先(とりひきさき)にどのような内容(ないよう)のメールを書(か)きますか。\n男(おとこ)：課長(かちょう)、ただいま帰(き)りました。\n女(おんな)：ご苦労(くろう)さん。どうだった？\n男(おとこ)：うまくいきましたよ。決(き)まりです。\n女(おんな)：そう。アサヒ製作所(せいさくしょ)さん、見積(みつも)もりの条件(じょうけん)、のんでくれた？\n男(おとこ)：いえ、けっこう粘(ねば)られました。\n女(おんな)：そうだろうね。\n男(おとこ)：ええ。でも、他社(たしゃ)の条件(じょうけん)、引合(ひきあ)いに出(だ)したら、しぶしぶでしたけど、首(くび)をタテに振(ふ)ってくれました。\n女(おんな)：そう！\n男(おとこ)：早速(さっそく)、契約書(けいやくしょ)、整(ととの)えます。\n女(おんな)：うん。あ、契約書(けいやくしょ)できたら、事前(じぜん)に、案(あん)を先方(せんぽう)にメールしといてね。\n男(おとこ)：はい。\n女(おんな)：それと、旅費(りょひ)の精算書(せいさんしょ)も早(はや)くね。\n男(おとこ)の人(ひと)は、このあと、取引先(とりひきさき)にどのような内容(ないよう)のメールを書(か)きますか。\n① 見積書(みつもりしょ)\n② 契約書(けいやくしょ)\n③ 契約書(けいやくしょ)の案(あん)\n④ 旅費(りょひ)の精算書(せいさんしょ)",
    "translationZhTW": "一名男子和一名女子正在交談。\n男子接下來會寄什麼內容的Email給客戶？\n男：課長，我回來了。\n女：辛苦了。怎麼樣？\n男：很順利，談成了。\n女：這樣啊。旭製作所接受我們報價的條件了嗎？\n男：沒有，他們可是談了很久。\n女：我想也是。\n男：是啊。不過我把其他公司的條件拿出來比較，他們雖然不太情願，最後還是點頭了。\n女：真的！\n男：我馬上整理合約。\n女：好。合約做完後，先把草案用Email寄給對方喔。\n男：好。\n女：還有，出差旅費的報銷單也快點處理。\n男子接下來會寄什麼內容的Email給客戶？\n① 報價單\n② 正式合約\n③ 合約草案\n④ 出差旅費報銷單",
