    "id": "BJT_JP02_P1_S3_Q10",
    "transcript": "男の人と女の人が、見本市の会場で話しています。\n女の人は、何を心配していますか。\n女：そろそろ、ブースにものを並べたいんですけど、荷物はどこですか。\n男1：えっ、ブースになかったんですか？\n女：はい、ブースに行ったんですけど……。\n男1：確か、まだ、いくつか荷物、届いてないって言ってたなあ。いつ頃、配送されたんですか？\n女：うーん、昨日の夕方届くように送ったんですが……。おかしいですね。\n男1：あっ、そういえば、昨日の朝、高速道路で大きな事故があったんですよ。上下線が、丸1日通行止めだったんですよね。\n女：今日も、まだ、だめなのかしら。\n男2：いや、事故処理は、昨日の夜遅く終わったみたいですよ。\n女：明日からの見本市、大丈夫かなあ。まあ、会社には配送車両の事故の連絡も入ってないし……。開通してるんだったら、お昼には着くはずよね……。\n女の人は、何を心配していますか。\n① 陳列の準備が間に合うかどうか\n② 運送会社の車が事故にあったかどうか\n③ 事故処理が終わったかどうか\n④ 見本市が中止になるかどうか",
    "transcriptWithFurigana": "男(おとこ)の人(ひと)と女(おんな)の人(ひと)が、見本市(みほんいち)の会場(かいじょう)で話(はな)しています。\n女(おんな)の人(ひと)は、何(なに)を心配(しんぱい)していますか。\n女(おんな)：そろそろ、ブースにものを並(なら)べたいんですけど、荷物(にもつ)はどこですか。\n男(おとこ)1：えっ、ブースになかったんですか？\n女(おんな)：はい、ブースに行(い)ったんですけど……。\n男(おとこ)1：確(かく)か、まだ、いくつか荷物(にもつ)、届(とど)いてないって言(い)ってたなあ。いつ頃(ころ)、配送(はいそう)されたんですか？\n女(おんな)：うーん、昨(さく)日(にち)の夕方(ゆうがた)届(とど)くように送(おく)ったんですが……。おかしいですね。\n男(おとこ)1：あっ、そういえば、昨(さく)日(にち)の朝(あさ)、高速道路(こうそくどうろ)で大(おお)きな事故(じこ)があったんですよ。上下線(じょうげせん)が、丸(まる)1日(いちにち)通(つう)行(ど)めだったんですよね。\n女(おんな)：今日(きょう)も、まだ、だめなのかしら。\n男(おとこ)2：いや、事故処理(じこしょり)は、昨(さく)日(にち)の夜(よる)遅(おそ)く終(お)わったみたいですよ。\n女(おんな)：明日(あした)からの見本市(みほんいち)、大丈夫(だいじょうぶ)かなあ。まあ、会社(かいしゃ)には配送車両(はいそうしゃりょう)の事故(じこ)の連絡(れんらく)も入(はい)ってないし……。開通(かいつう)してるんだったら、お昼(ひる)には着(つ)くはずよね……。\n女(おんな)の人(ひと)は、何(なに)を心配(しんぱい)していますか。\n① 陳列(ちんれつ)の準備(じゅんび)が間(ま)に合(あ)うかどうか\n② 運送会社(うんそうがいしゃ)の車(くるま)が事故(じこ)にあったかどうか\n③ 事故処理(じこしょり)が終(お)わったかどうか\n④ 見本市(みほんいち)が中止(ちゅうし)になるかどうか",
    "translationZhTW": "一名男子和一名女子正在展覽會場交談。\n女子在擔心什麼？\n女：差不多該把東西擺到攤位上了，貨物在哪裡？\n男1：咦？攤位那邊沒有嗎？\n女：對，我去攤位看過了……。\n男1：記得好像有人說還有幾件貨沒到。什麼時候寄出的？\n女：我是安排昨天傍晚送達的……。真奇怪。\n男1：啊，這麼說來，昨天早上高速公路發生了很大的事故，上下行整整一天都封路。\n女：今天也還不通嗎？\n男2：不，事故處理好像昨晚很晚就結束了。\n女：明天開始的展覽會沒問題吧……。公司也沒有收到配送車輛出事故的通知，而且既然道路已經恢復通車，中午應該會到吧……。\n女子在擔心什麼？\n① 展示陳列的準備是否來得及\n② 運輸公司的車是否發生事故\n③ 事故處理是否已結束\n④ 展覽會是否會取消",
