    "transcript": "ある会社の営業部で、部長と部下が、会議の準備について話しています。\n部下は、このあと最初に、何をしますか。\n男1：いよいよ、来年度の事業計画をまとめる時期に入ったね。来月の役員会の準備は、どう？\n男2：ええ。資料は、揃いつつあります。ただ、その前に、もう1度、部内の調整をしておく必要があると思うんですが。\n男1：そうだね。じゃ、今週中に、1度、時間を作りましょう。\n男2：はい。\n男1：それまでに、役員会とは別の資料がいるけど、用意できるかな。\n男2：ええ。一両日中に、用意できます。\n男1：そう。じゃ、頼むよ。いまやってるプロジェクトは、これからが正念場だからね。\n男2：そうですね。これから、やっと収益が出るというところまで、きましたからね。\n男1：うん。あ、部内での調整ももちろんだけど、企画部の部長とも、1度、話しといたほうがいいかな。\n男2：それなら、わたしより、部長のほうからお話ししていただいたほうが。\n男1：わかった。じゃ、それは、わたしがやろう。\n部下は、このあと最初に、何をしますか。\n① 役員会の資料を作る。\n② 部内会議の資料を作る。\n③ 部内の意見を調整する。\n④ 企画部との調整をする。",
