    "translationZhTW": "某公司業務部的部長和部下正在準備會議。\n部下接下來最先要做什麼？\n男1：終於到了彙整下一年度事業計畫的時期了。下個月董事會的準備怎麼樣？\n男2：資料正在陸續備齊。不過在那之前，我想有必要再做一次部門內部協調。\n男1：對。那這週找個時間開一次會。\n男2：好。\n男1：在那之前，需要一份跟董事會不同的資料，能準備嗎？\n男2：可以，一兩天內能準備好。\n男1：好，那就拜託你了。現在進行的專案接下來才是關鍵時期。\n男2：是啊，好不容易快到能開始產生收益的階段了。\n男1：嗯。啊，除了部門內協調之外，我是不是也該跟企劃部長談一次？\n男2：那件事由部長您親自談，應該比由我去說好。\n男1：知道了，那就由我來。\n部下接下來最先要做什麼？\n① 製作董事會資料。\n② 製作部門內會議資料。\n③ 協調部門內意見。\n④ 與企劃部協調。",
