    "id": "BJT_JP02_P1_S3_Q13",
    "transcript": "女の人が、パソコンの増産体制について、会議で報告しています。\nまだ解決していない問題は、何ですか。\n女：ノートパソコンを増産するにあたりまして、部品の供給、そして、ワーカーの確保が問題となっていましたが、本日は、調査の結果をご報告いたします。\nえー、まず、部品のサプライヤーですが、今回、定評のある2社を、新たに加えることに成功いたしました。また、現在ある5社も、供給能力に問題はないと思われます。\n次に、ワーカーの手配についてですが、常時採用可能な期間工を100名確保いたしました。この状況は、今後、半年間は変わらない見通しです。\nただ、半年後に、他社の新工場が稼働することがわかりまして、その際には、そちらに、かなり移る可能性があると思われます。その時点で、なおワーカーを確保できるかが、今回の目標達成の成否を、大きく左右すると思われます。\nまだ解決していない問題は、何ですか。\n① 部品の生産能力\n② 部品の供給元の確保\n③ 新工場の稼働率\n④ 今後の労働力の確保",
    "transcriptWithFurigana": "女(おんな)の人(ひと)が、パソコンの増産体制(ぞうさんたいせい)について、会議(かいぎ)で報告(ほうこく)しています。\nまだ解決(かいけつ)していない問題(もんだい)は、何(なに)ですか。\n女(おんな)：ノートパソコンを増産(ぞうさん)するにあたりまして、部(ぶ)品(ひん)の供給(きょうきゅう)、そして、ワーカーの確保(かくほ)が問題(もんだい)となっていましたが、本日(ほんじつ)は、調査(ちょうさ)の結果(けっか)をご報告(ほうこく)いたします。\nえー、まず、部(ぶ)品(ひん)のサプライヤーですが、今回(こんかい)、定評(ていひょう)のある2社(しゃ)を、新(しん)たに加(くわ)えることに成功(せいこう)いたしました。また、現在(げんざい)ある5社(しゃ)も、供給能力(きょうきゅうのうりょく)に問題(もんだい)はないと思(おも)われます。\n次(つぎ)に、ワーカーの手配(てはい)についてですが、常時採用可能(じょうじさいようかのう)な期間工(きかんこう)を100名確保(めいかくほ)いたしました。この状況(じょうきょう)は、今後(こんご)、半年間(はんとしかん)は変(か)わらない見通(みとお)しです。\nただ、半年後(はんとしご)に、他社(たしゃ)の新工場(しんこうじょう)が稼働(かどう)することがわかりまして、その際(さい)には、そちらに、かなり移(うつ)る可能性(かのうせい)があると思(おも)われます。その時点(じてん)で、なおワーカーを確保(かくほ)できるかが、今回(こんかい)の目標達成(もくひょうたっせい)の成否(せいひ)を、大(おお)きく左右(さゆう)すると思(おも)われます。\nまだ解決(かいけつ)していない問題(もんだい)は、何(なに)ですか。\n① 部(ぶ)品(ひん)の生産能力(せいさんのうりょく)\n② 部(ぶ)品(ひん)の供給元(きょうきゅうもと)の確保(かくほ)\n③ 新工場(しんこうじょう)の稼働率(かどうりつ)\n④ 今後(こんご)の労働力(ろうどうりょく)の確保(かくほ)",
    "translationZhTW": "一名女性在會議上報告增加筆電產量的生產體制。\n目前還沒有解決的問題是什麼？\n女：在增加筆記型電腦產量時，零件供應以及作業人員的確保一直是問題。今天我來報告調查結果。\n首先是零件供應商。這次我們成功新增了兩家有良好口碑的供應商，目前原有的五家公司在供應能力方面也看來沒有問題。\n接著是人力安排。我們已經確保100名可隨時錄用的期間工，預計未來半年這個狀況不會改變。\n不過我們得知半年後其他公司的新工廠將開始運作，到時候相當一部分人可能轉去那邊。屆時我們是否還能繼續確保作業人員，將大幅影響這次目標能否達成。\n目前還沒有解決的問題是什麼？\n① 零件的生產能力\n② 確保零件供應來源\n③ 新工廠的稼動率\n④ 未來勞動力的確保",
