    "transcript": "コンピュータ会社で、上司と部下が話しています。\n部下は、このあと、会議でどんなことを提案しますか。\n男1：このところ、売り上げが落ちてるね。\n男2：ええ、そうなんですよ。去年の同じ時期と比べると、今月は、3割減です。\n男1：そんなに落ち込んでるのか。\n男2：ええ。\n男1：これじゃ値下げしても、追いつかんね。\n男2：そうですね。\n男1：いままで、デザインや機能を変えたり、いろいろやったけど……。\n男2：はい。宣伝にも、人とお金をじゅうぶんにかけてます。\n男1：なにか別のアプローチが必要かな。\n男2：はい。実は……。\n男1：うん？\n男2：ユーザーのニーズに合わせて、カスタマイズして売るんです。\n男1：カスタマイズ？\n男2：はい。ユーザー一人ひとりの注文に応えるんです。\n男1：なるほど。\n男2：1度、会議にあげさせていただけませんか。\n男1：うん。じゃあ、その前に、もう少し詳しく聞かせてもらえるかな。\n男2：はい。\n部下は、このあと会議で、どんなことを提案しますか。\n① 価格の変更\n② デザインの変更\n③ 宣伝の方法\n④ 販売の方法",
    "transcriptWithFurigana": "コンピュータ会社(かいしゃ)で、上司(じょうし)と部下(ぶか)が話(はな)しています。\n部下(ぶか)は、このあと、会議(かいぎ)でどんなことを提案(ていあん)しますか。\n男(おとこ)1：このところ、売(う)り上(あ)げが落(お)ちてるね。\n男(おとこ)2：ええ、そうなんですよ。去年(きょねん)の同(おな)じ時期(じき)と比(くら)べると、今月(こんげつ)は、3割減(わりげん)です。\n男(おとこ)1：そんなに落(お)ち込(こ)みんでるのか。\n男(おとこ)2：ええ。\n男(おとこ)1：これじゃ値下(ねさ)げしても、追(お)いつかんね。\n男(おとこ)2：そうですね。\n男(おとこ)1：いままで、デザインや機能(きのう)を変(か)えたり、いろいろやったけど……。\n男(おとこ)2：はい。宣伝(せんでん)にも、人(ひと)とお金(かね)をじゅうぶんにかけてます。\n男(おとこ)1：なにか別(べつ)のアプローチが必要(ひつよう)かな。\n男(おとこ)2：はい。実(じつ)は……。\n男(おとこ)1：うん？\n男(おとこ)2：ユーザーのニーズに合(あ)わせて、カスタマイズして売(う)るんです。\n男(おとこ)1：カスタマイズ？\n男(おとこ)2：はい。ユーザー一人(ひとり)ひとりの注文(ちゅうもん)に応(こた)えるんです。\n男(おとこ)1：なるほど。\n男(おとこ)2：1度(ど)、会議(かいぎ)にあげさせていただけませんか。\n男(おとこ)1：うん。じゃあ、その前(まえ)に、もう少(すく)し詳(くわ)しく聞(き)かせてもらえるかな。\n男(おとこ)2：はい。\n部下(ぶか)は、このあと会議(かいぎ)で、どんなことを提案(ていあん)しますか。\n① 価格(かかく)の変更(へんこう)\n② デザインの変更(へんこう)\n③ 宣伝(せんでん)の方法(ほうほう)\n④ 販売(はんばい)の方法(ほうほう)",
    "translationZhTW": "在一家電腦公司，上司和部下正在交談。\n部下接下來會在會議上提出什麼建議？\n男1：最近銷售量在下降啊。\n男2：是啊。跟去年同期相比，這個月少了三成。\n男1：跌這麼多啊。\n男2：是。\n男1：這樣就算降價也追不回來啊。\n男2：是啊。\n男1：到現在為止，我們也改過設計、功能，做過很多嘗試……。\n男2：是。宣傳方面也投入了足夠的人力和預算。\n男1：看來需要其他做法。\n男2：是。其實……。\n男1：嗯？\n男2：按照使用者的需求，客製化之後再銷售。\n男1：客製化？\n男2：對，針對每一位使用者的個別訂單來回應。\n男1：原來如此。\n男2：可以讓我在會議上提案一次嗎？\n男1：好。不過在那之前，可以再詳細跟我說明一下嗎？\n男2：可以。\n部下接下來會在會議上提出什麼建議？\n① 更改價格\n② 更改設計\n③ 宣傳方式\n④ 銷售方式",
