    "transcript": "2人の会社員が、出張先での仕事について話しています。\n出張の目的は、何ですか。\n男：大阪は久しぶりだなあ。\n女：そうですね。本当は、もっといい話をしに行きたいところですけどね。\n男：まあ、つきあいの長いところだから、こちらの事情もご存知とは思うけど。\n女：そうですか。\n男：でも、こういうときは、ちゃんと先方の顔を見て、ご説明するのが一番だね。\n出張の目的は、何ですか。",
    "transcriptWithFurigana": "2人(ふたり)の会社員(かいしゃいん)が、出張(しゅっちょう)先(さき)での仕事(しごと)について話(はな)しています。\n出張(しゅっちょう)の目的(もくてき)は、何(なに)ですか。\n男(おとこ)：大阪(おおさか)は久(ひさ)しぶりだなあ。\n女(おんな)：そうですね。本当(ほんとう)は、もっといい話(はな)をしに行(い)きたいところですけどね。\n男(おとこ)：まあ、つきあいの長(なが)いところだから、こちらの事情(じじょう)もご存知(ぞんじ)とは思(おも)うけど。\n女(おんな)：そうですか。\n男(おとこ)：でも、こういうときは、ちゃんと先方(せんぽう)の顔(かお)を見(み)て、ご説明(せつめい)するのが一番(いちばん)だね。\n出張(しゅっちょう)の目的(もくてき)は、何(なに)ですか。",
