    "id": "BJT_JP02_P2_S2_Q03",
    "transcript": "課長から電話がかかってきました。\n女の人は、部長のどの時間帯について、都合を聞きますか。\n女：はい。サクラ食品企画課です。\n男：山田ですが。\n女：あ、課長、おはようございます。\n男：部長いる？\n女：いま、会議中です。\n男：あ、そう。えーと、2時から、部長と打ち合わせの予定だったんだけど、先方の都合で遅れそうなんですよ。\n女：あ、そうですか。\n男：申し訳ないんだけど、部長のこのあとのスケジュール、ちょっと見てもらえませんか。\n女：はい。えーっと、2時以降は…、4時から役員室で、それが30分の予定です。\n男：うん。\n女：あとは、夜、会合が6時っていうのがありますが。\n男：んー、そうか。じゃ、役員室の前に、入れるかな。\n女：そうですねえ。\n男：メモ、入れて、確認してもらえますか。\n女：はい、わかりました。\n男：じゃ、よろしく。\n女の人は、部長のどの時間帯について、都合を聞きますか。",
    "transcriptWithFurigana": "課長(かちょう)から電話(でんわ)がかかってきました。\n女(おんな)の人(ひと)は、部長(ぶちょう)のどの時間帯(じかんたい)について、都合(つごう)を聞(き)きますか。\n女(おんな)：はい。サクラ食品企画課(しょくひんきかくか)です。\n男(おとこ)：山田(やまだ)ですが。\n女(おんな)：あ、課長(かちょう)、おはようございます。\n男(おとこ)：部長(ぶちょう)いる？\n女(おんな)：いま、会議中(かいぎちゅう)です。\n男(おとこ)：あ、そう。えーと、2時(じ)から、部長(ぶちょう)と打(う)ち合(あ)わせの予定(よてい)だったんだけど、先方(せんぽう)の都合(つごう)で遅(おく)れそうなんですよ。\n女(おんな)：あ、そうですか。\n男(おとこ)：申(もう)し訳(わけ)ないんだけど、部長(ぶちょう)のこのあとのスケジュール、ちょっと見(み)てもらえませんか。\n女(おんな)：はい。えーっと、2時以降(じいこう)は…、4時(じ)から役員室(やくいんしつ)で、それが30分(ぶん)の予定(よてい)です。\n男(おとこ)：うん。\n女(おんな)：あとは、夜(よる)、会合(かいごう)が6時(じ)っていうのがありますが。\n男(おとこ)：んー、そうか。じゃ、役員室(やくいんしつ)の前(まえ)に、入(い)れるかな。\n女(おんな)：そうですねえ。\n男(おとこ)：メモ、入(い)れて、確(かく)認(にん)してもらえますか。\n女(おんな)：はい、わかりました。\n男(おとこ)：じゃ、よろしく。\n女(おんな)の人(ひと)は、部長(ぶちょう)のどの時間帯(じかんたい)について、都合(つごう)を聞(き)きますか。",
    "translationZhTW": "課長打電話來。\n女子要詢問部長哪一段時間是否方便？\n女：您好，這裡是櫻花食品企劃課。\n男：我是山田。\n女：啊，課長，早安。\n男：部長在嗎？\n女：現在正在開會。\n男：這樣啊。我原本預定2點跟部長開會，不過因為對方的情況，可能會晚一點。\n女：這樣啊。\n男：不好意思，可以幫我看一下部長接下來的行程嗎？\n女：好的。2點之後……4點開始在役員室有行程，預定30分鐘。\n男：嗯。\n女：另外晚上6點還有一個聚會。\n男：嗯……。那能不能排在去役員室之前？\n女：應該可以。\n男：可以留張便條，請部長確認嗎？\n女：好的，知道了。\n男：那就麻煩了。\n女子要詢問部長哪一段時間是否方便？",
