    "id": "BJT_JP02_P2_S2_Q06",
    "transcript": "プリンタのメーカーから、お知らせが届きました。\nこの会社が使っているプリンタは、どれですか。\n女：課長、プリンタのメーカーから、こんなのが届きましたけど。\n男：え？何？\n女：プリンタの欠陥が、わかったらしいんですよ。\n男：どんな欠陥？\n女：えっと、異常な発熱が起こる場合があるって、書いてあります。\n男：ありゃ、それは困るねえ。で、うちで使ってるの？それ。\n女：あれですが。……えーっと、レーザープレスですね。\n男：型番は？\n女：えー、ヨン・イチ・ゴー・ゼロ、それから、ピーなんとか。シールがはがれて、ちょっと読めません。\n男：それ、いつ買ってるの？\n女：ちょっと待ってください。…はい、02年の8月期って書いてあります。\n男：じゃ、これか。\n女：そうですね。部品交換ですね。\nこの会社が使っているプリンタは、どれですか。",
    "transcriptWithFurigana": "プリンタのメーカーから、お知(し)らせが届(とど)きました。\nこの会社(かいしゃ)が使(つか)っているプリンタは、どれですか。\n女(おんな)：課長(かちょう)、プリンタのメーカーから、こんなのが届(とど)きましたけど。\n男(おとこ)：え？何(なに)？\n女(おんな)：プリンタの欠(けつ)陥(かん)が、わかったらしいんですよ。\n男(おとこ)：どんな欠(けつ)陥(かん)？\n女(おんな)：えっと、異常(いじょう)な発熱(はつねつ)が起(お)こる場合(ばあい)があるって、書(か)いてあります。\n男(おとこ)：ありゃ、それは困(こま)るねえ。で、うちで使(つか)ってるの？それ。\n女(おんな)：あれですが。……えーっと、レーザープレスですね。\n男(おとこ)：型番(かたばん)は？\n女(おんな)：えー、ヨン・イチ・ゴー・ゼロ、それから、ピーなんとか。シールがはがれて、ちょっと読(よ)めません。\n男(おとこ)：それ、いつ買(か)ってるの？\n女(おんな)：ちょっと待(ま)ってください。…はい、02年(ねん)の8月期(がつき)って書(か)いてあります。\n男(おとこ)：じゃ、これか。\n女(おんな)：そうですね。部品交換(ぶひんこうかん)ですね。\nこの会社(かいしゃ)が使(つか)っているプリンタは、どれですか。",
    "translationZhTW": "印表機製造商寄來一份通知。\n這家公司使用的是哪一台印表機？\n女：課長，印表機製造商寄來這個通知。\n男：咦？什麼？\n女：好像發現印表機有瑕疵。\n男：什麼瑕疵？\n女：上面寫說有時候會發生異常發熱。\n男：哎呀，那就麻煩了。所以我們公司有用這一款嗎？\n女：是那台……嗯，是Laser Press。\n男：型號呢？\n女：嗯，四、一、五、零，然後P什麼的。貼紙掉了，有點看不清楚。\n男：那台是什麼時候買的？\n女：請等一下……好，上面寫02年8月期。\n男：那就是這一台了。\n女：對。要更換零件了。\n這家公司使用的是哪一台印表機？",
